/**
 * NodeService Bond Management — PROPERLY ENCAPSULATED.
 * Typed `BondDeps` interface instead of `self: any`.
 */

import type { HelloProfile, HelloResponse, SendHelloOptions } from "@envoymesh/api";

// ── Deps interface ──────────────────────────────────────────────────────────

export interface BondDeps {
  // Mesh / profile assertions
  assertOnline(): void;
  requireMesh(): any;
  requireProfile(): any;

  // Intro proposals state
  pendingSocialIntroProposals: Map<string, any>;

  // Peer directory + trust
  getPeerDirectoryStore(): any;
  getTrustStore(): any;

  // Transport helpers
  dialHintsForChat(peerId: string, addrs?: any): Promise<string[]>;
  deliverCallEnvelope(peerId: string, env: any, hints?: any, addrs?: any, preferCircuit?: boolean): Promise<void>;
  tagBondedContactReachability(peerId: string): Promise<void>;
  resolvePeerTransportForOwner(ownerId: string): Promise<{ transportPeerId: string; recipientEnvelopePeerId?: string; listenAddrs?: string[] }>;
}

// ── sendHello ───────────────────────────────────────────────────────────────

export async function sendHello(
  deps: BondDeps,
  targetOwnerId: string,
  profile: HelloProfile,
  message: string,
  options?: SendHelloOptions,
): Promise<HelloResponse> {
  deps.assertOnline();
  const mesh = deps.requireMesh();
  const selfProfile = deps.requireProfile();

  let introCorrelationId: string | undefined;
  let ownerCommitmentRef: string | undefined;
  let pendingIntro: any;

  if (options?.introProposalMessageId) {
    pendingIntro = deps.pendingSocialIntroProposals.get(options.introProposalMessageId);
    if (!pendingIntro) throw new Error(`No pending intro proposal for messageId=${options.introProposalMessageId}`);
    if (!pendingIntro.ownerCommitmentRef) throw new Error("Approve the intro commitment before sending hello");
    if (pendingIntro.candidateOwnerId.trim() !== targetOwnerId.trim()) throw new Error("Intro proposal candidate does not match hello target owner id");
    introCorrelationId = pendingIntro.introCorrelationId;
    ownerCommitmentRef = pendingIntro.ownerCommitmentRef;
  }

  const peerRecords = await deps.getPeerDirectoryStore().listPeerRecords();
  let matchedRecord = peerRecords.find((r: any) => r.ownerId === targetOwnerId) ?? peerRecords.find((r: any) => r.peerId === targetOwnerId);
  let targetPeerId = matchedRecord?.peerId;

  if (pendingIntro?.candidatePeerId) {
    targetPeerId = pendingIntro.candidatePeerId;
    matchedRecord = peerRecords.find((r: any) => r.ownerId === pendingIntro.candidateOwnerId) ?? peerRecords.find((r: any) => r.peerId === pendingIntro.candidatePeerId);
  }

  if (!targetPeerId) {
    if (targetOwnerId.startsWith("Qm") || targetOwnerId.startsWith("12D3")) {
      targetPeerId = targetOwnerId;
    } else {
      throw new Error(`Peer not found for owner: ${targetOwnerId}`);
    }
  }

  const { createUnsignedEnvelope, createBondRequestPayload } = await import("@envoymesh/protocol");
  const { derivePeerId, signUnsignedEnvelope } = await import("@envoymesh/identity");

  const envelope = signUnsignedEnvelope(
    createUnsignedEnvelope({
      senderPeerId: derivePeerId(selfProfile.device.publicKeyPem),
      senderPublicKey: selfProfile.device.publicKeyPem,
      recipientPeerId: targetPeerId,
      intent: "bond.request",
      payload: createBondRequestPayload({
        requesterOwnerId: selfProfile.owner.ownerId,
        requesterDisplayName: profile.displayName,
        message: `[HELLO] ${message}`,
        proofOfContext: `displayName:${profile.displayName}`,
        requestedLevel: "direct",
        introCorrelationId,
        ownerCommitmentRef,
      }),
    }),
    selfProfile.device.privateKeyPem,
  );

  try {
    const dialHints = await deps.dialHintsForChat(targetPeerId, matchedRecord?.listenAddrs);
    await deps.deliverCallEnvelope(targetPeerId, envelope, dialHints, matchedRecord?.listenAddrs);

    if (options?.introProposalMessageId) {
      deps.pendingSocialIntroProposals.delete(options.introProposalMessageId);
    }

    try {
      await deps.getPeerDirectoryStore().ensurePeerFromInboundChat({
        ownerId: targetOwnerId, peerId: targetPeerId, listenAddrs: matchedRecord?.listenAddrs ?? [],
      });
    } catch (err) {
      console.warn(`[peer-directory] sendHello ensurePeerFromInboundChat:`, err);
    }
    void deps.tagBondedContactReachability(targetPeerId);

    return { status: "sent", timestamp: new Date().toISOString(), messageId: envelope.messageId };
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { status: "error", error: msg, timestamp: new Date().toISOString() };
  }
}

