+++ b//Users/shileipeng/Documents/mygithub/EnvoyMesh/apps/node/src/node-service-social-proxy.ts
@@ -0,0 +1,310 @@
+/**
+ * NodeService Social Proxy Handlers — PROPERLY ENCAPSULATED.
+ * Typed `SocialProxyDeps` interface instead of `self: any`.
+ * Each function takes the deps bag as the first argument.
+ *
+ * Migrated from `node-service-impl.ts`:
+ *   storePendingHelloRequest, storePendingSocialIntroProposal,
+ *   listPendingSocialIntroProposals, approveSocialIntroCommitment,
+ *   handleSocialProxyPeerOwnerReady, sendSocialIntroOwnerReady,
+ *   declineSocialIntroProposal
+ *
+ * NOTE: `sendSocialIntroOwnerReady` was previously `_sendSocialIntroOwnerReady`
+ * (private). The leading underscore is dropped because the function is now an
+ * exported module binding; consumers receive it through `SocialProxyDeps`,
+ * so it does not pollute NodeServiceImpl's public surface.
+ */
+
+import { randomUUID } from "node:crypto";
+import { createUnsignedEnvelope, createSocialIntroOwnerReadyPayload } from "@envoymesh/protocol";
+import { derivePeerId, signUnsignedEnvelope } from "@envoymesh/identity";
+import { createAuditEvent, type LocalTaskStore } from "@envoymesh/local-store";
+import { transitionSocialProxySession, type AgentActivityRecord, type SocialIntroProposal, type SocialProxySession } from "@envoymesh/api";
+import type { LocalAgentActivityStore } from "@envoymesh/local-store";
+import type { SocialProxySessionStore } from "@envoymesh/local-store";
+import type { NodeConfig, NodeProfile, EnvoyMesh } from "@envoymesh/api";
+import type { EnvoyEnvelope } from "@envoymesh/protocol";
+
+// ── Deps interface ──────────────────────────────────────────────────────────
+
+export interface SocialProxyDeps {
+  // Mesh / profile access
+  reachableMesh(): EnvoyMesh | undefined;
+  getProfile(): NodeProfile | undefined;
+
+  // Config
+  getNodeConfig(): Promise<NodeConfig>;
+
+  // Pending proposal state
+  pendingHelloRequests: Map<
+    string,
+    {
+      remotePeerId: string;
+      requesterOwnerId: string;
+      requesterDisplayName: string;
+      message: string;
+      requestedLevel: string;
+      createdAt: string;
+    }
+  >;
+  pendingSocialIntroProposals: Map<string, SocialIntroProposal & { ownerCommitmentRef?: string }>;
+
+  // Optional stores
+  getSocialProxyStore(): SocialProxySessionStore | null;
+  getTaskStore(): LocalTaskStore | undefined;
+  getAgentActivityStore(): LocalAgentActivityStore | null;
+
+  // Activity publish + emit
+  publishAgentActivity(record: AgentActivityRecord, contactOwnerId?: string): Promise<void>;
+  emit(event: string, data: unknown): void;
+
+  // Orchestrator delegation
+  advanceSocialProxySession(sessionId: string): Promise<SocialProxySession | undefined>;
+
+  // Transport helpers
+  resolvePeerTransportForOwner(ownerId: string): Promise<{
+    transportPeerId: string;
+    recipientEnvelopePeerId?: string;
+    listenAddrs?: string[];
+  }>;
+  dialHintsForChat(recipientPeerId: string, peerListenAddrs: string[] | undefined): Promise<string[]>;
+  deliverCallEnvelope(
+    transportPeerId: string,
+    envelope: EnvoyEnvelope,
+    dialHints: string[],
+    peerListenAddrs?: string[],
+    preferCircuit?: boolean,
+  ): Promise<void>;
+
+  // Companion helper for `approveSocialIntroCommitment` — sends the owner-ready envelope.
+  sendSocialIntroOwnerReady(
+    row: SocialIntroProposal & { ownerCommitmentRef?: string },
+  ): Promise<boolean>;
+}
+
+// ── storePendingHelloRequest ────────────────────────────────────────────────
+
+export function storePendingHelloRequest(
+  deps: SocialProxyDeps,
+  data: {
+    messageId: string;
+    sender: { nodeId: string; ownerId: string; displayName: string };
+    message: string;
+    timestamp: string;
+  },
+): void {
+  const existing = deps.pendingHelloRequests.get(data.messageId);
+  if (!existing) {
+    deps.pendingHelloRequests.set(data.messageId, {
+      remotePeerId: data.sender.nodeId,
+      requesterOwnerId: data.sender.ownerId,
+      requesterDisplayName: data.sender.displayName ?? data.sender.ownerId,
+      message: data.message,
+      requestedLevel: "direct",
+      createdAt: data.timestamp,
+    });
+    console.log(`[node-service] stored pending hello request: messageId=${data.messageId}, from=${data.sender.ownerId}`);
+  }
+}
+
+// ── storePendingSocialIntroProposal ─────────────────────────────────────────
+
+export function storePendingSocialIntroProposal(
+  deps: SocialProxyDeps,
+  proposal: SocialIntroProposal,
+): void {
+  const { commitmentApproved: _ca, ...rest } = proposal;
+  void _ca;
+  if (deps.pendingSocialIntroProposals.has(rest.messageId)) {
+    return;
+  }
+  deps.pendingSocialIntroProposals.set(rest.messageId, {
+    ...rest,
+    ownerCommitmentRef: undefined,
+  });
+  deps.emit("social.intro:propose", { ...rest, commitmentApproved: false });
+}
+
+// ── listPendingSocialIntroProposals ─────────────────────────────────────────
+
+export async function listPendingSocialIntroProposals(
+  deps: SocialProxyDeps,
+): Promise<SocialIntroProposal[]> {
+  return [...deps.pendingSocialIntroProposals.values()].map((row) => {
+    const { ownerCommitmentRef, ...pub } = row;
+    return {
+      ...pub,
+      commitmentApproved: Boolean(ownerCommitmentRef),
+    };
+  });
+}
+
+// ── approveSocialIntroCommitment ────────────────────────────────────────────
+
+export async function approveSocialIntroCommitment(
+  deps: SocialProxyDeps,
+  messageId: string,
+): Promise<{ ownerCommitmentRef: string }> {
+  const row = deps.pendingSocialIntroProposals.get(messageId);
+  if (!row) {
+    throw new Error(`No pending intro proposal for messageId=${messageId}`);
+  }
+  if (!row.ownerCommitmentRef) {
+    row.ownerCommitmentRef = randomUUID();
+  }
+  const sent = await deps.sendSocialIntroOwnerReady(row);
+  if (!sent) {
+    throw new Error("Failed to send social.intro.owner-ready (mesh unavailable or send failed)");
+  }
+  return { ownerCommitmentRef: row.ownerCommitmentRef };
+}
+
+// ── handleSocialProxyPeerOwnerReady ─────────────────────────────────────────
+
+export async function handleSocialProxyPeerOwnerReady(
+  deps: SocialProxyDeps,
+  input: {
+    introCorrelationId: string;
+    ownerId: string;
+    nonce: string;
+    remotePeerId: string;
+    receivedAt: string;
+  },
+): Promise<SocialProxySession | undefined> {
+  void input.nonce;
+  const socialProxyStore = deps.getSocialProxyStore();
+  if (!socialProxyStore) return undefined;
+  const config = await deps.getNodeConfig();
+  if (!config.socialProxyEnabled) return undefined;
+
+  const sessions = await socialProxyStore.list();
+  const session = sessions.find(
+    (s) => s.correlationId === input.introCorrelationId && s.candidateOwnerId === input.ownerId,
+  );
+  if (!session) {
+    console.warn(
+      `[social-proxy] social.intro.owner-ready: no session for correlationId=${input.introCorrelationId} candidateOwnerId=${input.ownerId}`,
+    );
+    const taskStore = deps.getTaskStore();
+    if (taskStore) {
+      await taskStore.appendAuditEvent(
+        createAuditEvent({
+          type: "message.verified",
+          intent: "social.intro.owner-ready",
+          correlationId: input.introCorrelationId,
+          remotePeerId: input.remotePeerId,
+          direction: "inbound",
+          outcome: "record",
+          summary: `social.intro.owner-ready: no matching social proxy session (candidateOwnerId=${input.ownerId})`,
+          createdAt: input.receivedAt,
+        }),
+      );
+    }
+    return undefined;
+  }
+
+  let current = session;
+  if (current.status === "awaiting_peer") {
+    const peerReady = transitionSocialProxySession(current, "PEER_OWNER_READY");
+    if (peerReady.changed) current = peerReady.session;
+  }
+
+  const localRef = randomUUID();
+  if (current.introProposalMessageId) {
+    const row = deps.pendingSocialIntroProposals.get(current.introProposalMessageId);
+    if (row) row.ownerCommitmentRef = localRef;
+  }
+
+  const withRef = {
+    ...current,
+    ownerCommitmentRef: localRef,
+    updatedAt: new Date().toISOString(),
+  };
+  const { session: next } = transitionSocialProxySession(withRef, "OWNER_APPROVE_INTRO", {
+    hasOwnerCommitmentRef: true,
+  });
+  await socialProxyStore.save(next);
+
+  const agentActivityStore = deps.getAgentActivityStore();
+  if (agentActivityStore) {
+    const record: AgentActivityRecord = {
+      activityId: randomUUID(),
+      correlationId: next.correlationId,
+      taskId: next.sessionId,
+      domain: "social",
+      kind: "social_proxy_transition",
+      summary: `Social proxy: peer owner-ready → ${next.status}`,
+      remoteOwnerId: input.ownerId,
+      createdAt: new Date().toISOString(),
+    };
+    await agentActivityStore.append(record);
+    await deps.publishAgentActivity(record, input.ownerId);
+  }
+
+  void deps.advanceSocialProxySession(next.sessionId);
+  return next;
+}
+
+// ── sendSocialIntroOwnerReady ───────────────────────────────────────────────
+
+export async function sendSocialIntroOwnerReady(
+  deps: SocialProxyDeps,
+  row: SocialIntroProposal & { ownerCommitmentRef?: string },
+): Promise<boolean> {
+  const mesh = deps.reachableMesh();
+  const profile = deps.getProfile();
+  if (!mesh || !profile) return false;
+
+  try {
+    const { transportPeerId } = await deps.resolvePeerTransportForOwner(row.agentOwnerId);
+    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
+    const unsigned = createUnsignedEnvelope({
+      senderPeerId: derivePeerId(profile.device.publicKeyPem),
+      senderPublicKey: profile.device.publicKeyPem,
+      senderRole: "human",
+      recipientPeerId: row.agentPeerId,
+      recipientRole: "agent",
+      intent: "social.intro.owner-ready",
+      payload: createSocialIntroOwnerReadyPayload({
+        introCorrelationId: row.introCorrelationId,
+        ownerId: profile.owner.ownerId,
+        nonce: randomUUID(),
+        expiresAt,
+      }),
+      correlationId: row.introCorrelationId,
+    });
+    const signed = signUnsignedEnvelope(unsigned, profile.device.privateKeyPem);
+    const dialHints = await deps.dialHintsForChat(transportPeerId, undefined);
+    await deps.deliverCallEnvelope(transportPeerId, signed, dialHints);
+
+    const taskStore = deps.getTaskStore();
+    if (taskStore) {
+      await taskStore.appendAuditEvent(
+        createAuditEvent({
+          type: "message.sent",
+          intent: signed.intent,
+          messageId: signed.messageId,
+          correlationId: row.introCorrelationId,
+          remotePeerId: transportPeerId,
+          direction: "outbound",
+          outcome: "record",
+          summary: "Sent social.intro.owner-ready after intro commitment approval.",
+          createdAt: signed.createdAt,
+        }),
+      );
+    }
+    return true;
+  } catch (err) {
+    console.warn("[node-service] failed to send social.intro.owner-ready:", err);
+    return false;
+  }
+}
+
+// ── declineSocialIntroProposal ──────────────────────────────────────────────
+
+export async function declineSocialIntroProposal(
+  deps: SocialProxyDeps,
+  messageId: string,
+): Promise<void> {
+  deps.pendingSocialIntroProposals.delete(messageId);
+}

