async handleSocialProxyPeerOwnerReady(input: {
  introCorrelationId: string;
  ownerId: string;
  nonce: string;
  remotePeerId: string;
  receivedAt: string;
}): Promise<SocialProxySession | undefined> {
  void input.nonce;
  if (!this._socialProxyStore) return undefined;
